// Critic round 7, P1-1 / P2-1: a crafted 800 kB page froze the gateway for 107 s in web_read's htmlToText (quadratic
// regexes, webRead.js was not in the ReDoS test), and redactPatterns.js had polynomial rules (130 s on 199 kB). This test
// runs EVERY regex of EVERY gateway source file against runs with failing tails (64 kB) and against the recheck attack strings
// of fixtures/redos-attacks.json (64 kB and 200 kB; generated by recheck from the round-7 tree), 100 ms per regex and input.
// End to end: web_read of crafted 800 kB bodies returns within 2 s with a responsive event loop, and redact() fails closed
// within its budget. All inputs are synthetic.
import assert from 'node:assert/strict';
import fs from 'node:fs';
import { Readable } from 'node:stream';
import { after, describe, it } from 'node:test';
import { pumpAttack, regexesOf, scanInWorker, srcFiles, tailCorpus } from './helpers/redos.js';
import { createPool, createSyncRunner } from '../src/offload.js';
import { REDACT_BUDGET_MS, REDACT_FALLBACK, redact, redactAsync, setRedactOffloadForTests } from '../src/redact.js';
import { HTML_CAP, htmlToText, htmlToTextBudgeted, webRead } from '../src/webRead.js';
import { syn } from './synthetic.js';

const ATTACKS = JSON.parse(fs.readFileSync(new URL('./fixtures/redos-attacks.json', import.meta.url), 'utf8'));
const SRC = new URL('../src/', import.meta.url);
const BUDGET_MS = 100;
const TAIL = tailCorpus(64_000);
const rel = (u) => `gateway/src/${u.href.slice(SRC.href.length)}`;
const pumped = (list, sizes) => list.flatMap((a) => sizes.map((n) => [`recheck ${a.file}:${a.line} @${n}`, pumpAttack(a, n)]));
const report = (slow) => slow.slice(0, 8).map((s) => `${s.ms} ms ${s.where} [${s.name}, ${s.len} chars]`).join('\n');
// redact sees text of any shape, so its patterns get every attack of every file
const ANY_TEXT = new Set(['gateway/src/redactPatterns.js', 'gateway/src/redact.js']);

describe('every regex of every gateway file stays linear on failing-tail runs and recheck attacks (critic round 7)', () => {
  for (const file of srcFiles(SRC)) {
    it(`${rel(file)}: no regex over ${BUDGET_MS} ms`, async () => {
      const regexes = await regexesOf(file);
      if (!regexes.length) return;
      const own = ANY_TEXT.has(rel(file)) ? ATTACKS : ATTACKS.filter((a) => a.file === rel(file));
      const { slow } = await scanInWorker(regexes, [...TAIL, ...pumped(own, [64_000, 200_000])], BUDGET_MS, 240_000);
      assert.equal(slow.length, 0, `super-linear regexes in ${rel(file)}:\n${report(slow)}`);
    });
  }
  it('the fixture has the round-7 attacks of webRead.js and redactPatterns.js', () => {
    assert.ok(ATTACKS.filter((a) => a.file === 'gateway/src/webRead.js').length >= 10);
    assert.ok(ATTACKS.filter((a) => a.file === 'gateway/src/redactPatterns.js').length >= 10);
  });
});

/** Max gap between 10 ms ticks while `fn` runs: the event loop is free when it stays small. */
async function loopGap(fn) {
  let last = performance.now();
  let gap = 0;
  const timer = setInterval(() => { const t = performance.now(); gap = Math.max(gap, t - last); last = t; }, 10);
  try {
    const value = await fn();
    return { value, gap: Math.max(gap, performance.now() - last) };
  } finally {
    clearInterval(timer);
  }
}

const UNITS = { mix: '<a x ', comment: '<!--', title: '<TITLE>', lt: '<\u0000', ltsp: '< x ', meta: '<META=', p: '<p\u0000L' };
const page = (body, type = 'text/html') => ({
  lookup: async () => [{ address: '93.184.216.34', family: 4 }],
  transport: async () => ({ status: 200, headers: { 'content-type': type }, body: Readable.from([Buffer.from(body)]) }),
  rateLimit: () => true,
  key: 'redos',
});

describe('web_read of a crafted page cannot freeze the desk (critic round 7, P1-1)', () => {
  const bodies = [
    ...Object.entries(UNITS).map(([k, u]) => [k, `<html><body><p>Hallo</p>${u.repeat(Math.ceil(800_000 / u.length))}</body></html>`]),
    ...ATTACKS.filter((a) => a.file === 'gateway/src/webRead.js').map((a) => [`recheck webRead.js:${a.line}`, pumpAttack(a, 800_000)]),
  ];
  for (const [name, body] of bodies) {
    it(`${name} (${Math.round(body.length / 1000)} kB): answers within 2 s, the event loop stays responsive`, async () => {
      const t = performance.now();
      const { value, gap } = await loopGap(() => webRead({ url: 'https://pub.example.com/x' }, page(body)).then((r) => r, (e) => e));
      const ms = performance.now() - t;
      assert.ok(ms < 2_000, `${Math.round(ms)} ms`);
      assert.ok(gap < 250, `event loop blocked for ${Math.round(gap)} ms`);
      assert.ok(value.finalUrl || /Seite zu komplex/.test(value.message), String(value.message ?? ''));
    });
  }
  it('htmlToText caps the input and still finds the main part of a long page', () => {
    const html = `<html><head><title>T</title></head><body><nav>Menü</nav><main><p>${'Inhalt des Artikels. '.repeat(20)}</p>${'<p>Absatz</p>'.repeat(60_000)}</main></body></html>`;
    const r = htmlToText(html, new URL('https://x.example/'));
    assert.equal(r.title, 'T');
    assert.match(r.text, /^Inhalt des Artikels\./);
    assert.ok(!r.text.includes('Menü'));
  });
  it('a page over the budget is refused ("Seite zu komplex"), never parsed on the event loop', async () => {
    const html = `<p>${'x '.repeat(200_000)}</p>${'<p>Absatz <a href="https://x.example/a">Link</a></p>'.repeat(6_000)}`;
    await assert.rejects(htmlToTextBudgeted(html, new URL('https://x.example/'), 1), (err) => err.code === 'complex' && /Seite zu komplex/.test(err.message));
    const ok = await htmlToTextBudgeted(html, new URL('https://x.example/'));
    assert.ok(ok.text.startsWith('x x'));
  });
  it('a page cut at the cap keeps its text; only a tag split by the cut is dropped', () => {
    const r = htmlToText(`<p>${'Wort '.repeat(120_000)}</p>`, new URL('https://x.example/'));
    assert.ok(r.text.length > 500_000, String(r.text.length));
    const cut = htmlToText(`<p>${'a'.repeat(HTML_CAP - 10)}<span class="${'b'.repeat(100)}">x</span>`, new URL('https://x.example/'));
    assert.ok(!cut.text.includes('<span'), cut.text.slice(-40));
  });
});

describe('redact() has a hard budget and fails closed (critic round 7, P2-1)', () => {
  it(`every recheck attack at 200 kB: redact() and redactAsync() finish within the budget (${REDACT_BUDGET_MS} ms)`, async () => {
    // warm-up: the bridge loads its secret value list on the first call (~1 s) and the workers start once; both are not the budget
    redact(`warm ${'x'.repeat(10_000)}`);
    await redactAsync(`warm ${'x'.repeat(10_000)}`);
    for (const a of ATTACKS) {
      const text = pumpAttack(a, 200_000);
      let t = performance.now();
      redact(text);
      assert.ok(performance.now() - t < REDACT_BUDGET_MS + 500, `redact ${a.file}:${a.line} ${Math.round(performance.now() - t)} ms`);
      t = performance.now();
      const { gap } = await loopGap(() => redactAsync(text));
      assert.ok(performance.now() - t < REDACT_BUDGET_MS + 500, `redactAsync ${a.file}:${a.line} ${Math.round(performance.now() - t)} ms`);
      assert.ok(gap < 250, `redactAsync blocked the event loop for ${Math.round(gap)} ms (${a.file}:${a.line})`);
    }
  });
  it('big texts are redacted the same in the worker as inline, small ones stay inline', async () => {
    const secret = syn('OPENAI_API_KEY=Zq7x·Wv2P·Lk9m·Rt4Y·bN8c·Hs3G·aB1');
    const text = `${'Ein normaler Satz. '.repeat(2_000)}\n${secret}\n`;
    assert.equal(redact(text), `${'Ein normaler Satz. '.repeat(2_000)}\nOPENAI_API_KEY=[REDACTED]\n`);
    assert.equal(await redactAsync(text), redact(text));
    assert.equal(redact(secret), 'OPENAI_API_KEY=[REDACTED]');
  });
  it('a redaction that takes longer than the budget returns the fallback, never the text', async () => {
    const restore = setRedactOffloadForTests({ patterns: new URL('./fixtures/slow-redact.mjs', import.meta.url).href, budgetMs: 150 });
    try {
      const text = `${syn('OPENAI_API_KEY=Zq7x·Wv2P·Lk9m·Rt4Y·bN8c·Hs3G·aB1')} ${'x'.repeat(20_000)}`;
      let t = performance.now();
      assert.equal(redact(text), REDACT_FALLBACK);
      assert.ok(performance.now() - t < 1_000, `${Math.round(performance.now() - t)} ms`);
      t = performance.now();
      const { value, gap } = await loopGap(() => redactAsync(text));
      assert.equal(value, REDACT_FALLBACK);
      assert.ok(gap < 250, `${Math.round(gap)} ms`);
    } finally {
      restore();
    }
    assert.equal(redact(`${syn('OPENAI_API_KEY=Zq7x·Wv2P·Lk9m·Rt4Y·bN8c·Hs3G·aB1')} ${'x'.repeat(20_000)}`).slice(0, 25), 'OPENAI_API_KEY=[REDACTED]');
  });
});

describe('offload.js: pool and sync runner', () => {
  const SLOW = new URL('./fixtures/slow-redact.mjs', import.meta.url).href;
  const pool = createPool({ size: 1 });
  const sync = createSyncRunner();
  after(() => { pool.close(); sync.close(); });
  it('the pool terminates a task over budget and the next task gets a fresh worker', async () => {
    await assert.rejects(pool.run(SLOW, 'spin', [5_000], 100), (e) => e.code === 'budget');
    assert.equal(await pool.run(SLOW, 'echo', ['ok'], 2_000), 'ok');
  });
  it('the sync runner blocks at most the budget, then recovers', () => {
    const t = performance.now();
    assert.throws(() => sync.run(SLOW, 'spin', [5_000], 100), (e) => e.code === 'budget');
    assert.ok(performance.now() - t < 1_000);
    assert.equal(sync.run(SLOW, 'echo', ['ok'], 5_000), 'ok');
  });
  it('an error inside the task is an error, not a hang', async () => {
    await assert.rejects(pool.run(SLOW, 'boom', [], 2_000), /boom/);
    assert.throws(() => sync.run(SLOW, 'boom', [], 2_000), /boom/);
  });
});
